def main() -> None:
    if len(ROWS) != 50:
        raise RuntimeError(f"expected 50 quality QA rows, got {len(ROWS)}")
    out = REPO_ROOT / "data" / "eval" / "quality_qa_batch.jsonl"
    out.parent.mkdir(parents=True, exist_ok=True)
    prepared: list[tuple[str, str, str, str, str]] = []
    with out.open("w", encoding="utf-8") as handle:
        for item_id, topic, title, content, source in ROWS:
            body = content if content.endswith(SAFE_TAIL.strip()) else (content.rstrip() + SAFE_TAIL)
            prepared.append((item_id, topic, title, body, source))
            question = f"Прокомментируйте с позиций Ленина: {title[0].lower() + title[1:]}."
            handle.write(
                json.dumps(
                    {
                        "id": item_id,
                        "topic": topic,
                        "title": title,
                        "content": body,
                        "question": question,
                        "source": source,
                    },
                    ensure_ascii=False,
                )
                + "\n"
            )

    guard = NewsGuard(config=load_news_guard_config(path=REPO_ROOT / "config" / "news_guard.yaml"))
    blocked: list[tuple[str, str, str]] = []
    for item_id, _topic, title, content, source in prepared:
        result = guard.evaluate_input(title=title, content=content, source=source)
        if result.decision in {"deny", "quarantine"}:
            blocked.append((item_id, result.decision, result.reason))
    if blocked:
        raise SystemExit(f"NewsGuard blocked {len(blocked)}: {blocked[:8]}")
    print(f"wrote {out} n=50 guard_ok")


if __name__ == "__main__":
    main()
